#include <iostream>
#include <vector>
struct Result { int value = 0, rejected = 0; bool operator==(const Result&) const = default; };
Result replay(const std::vector<int>& trace) {
  Result r;
  for (int x : trace) { if (x < -10 || x > 10 || r.value + x < 0 || r.value + x > 10) ++r.rejected; else r.value += x; }
  return r;
}
int main() {
  int n;
  if (!(std::cin >> n) || n < 0 || n > 20) { std::cout << "invalid\n"; return 0; }
  std::vector<int> trace(n);
  for (int& x : trace) if (!(std::cin >> x)) { std::cout << "invalid\n"; return 0; }
  std::cin >> std::ws;
  if (!std::cin.eof()) { std::cout << "invalid\n"; return 0; }
  const Result a = replay(trace), b = replay(trace);
  if (!(a == b) || a.value < 0 || a.value > 10) return 1;
  std::cout << "value " << a.value << " rejected " << a.rejected << " replay PASS\n";
}
